<script setup>
import {computed,ref} from 'vue';import {useWorkspace} from '../stores/workspace.js';import Icon from '../components/Icon.vue';import RouteMap from '../components/RouteMap.vue';import ShipmentTable from '../components/ShipmentTable.vue';import ShipmentForm from '../components/ShipmentForm.vue';import ShipmentDetail from '../components/ShipmentDetail.vue';import {filterShipments,metrics,toCSV} from '../utils/shipments.js';
const store=useWorkspace(),period=ref('all'),selected=ref(null),form=ref(false),editing=ref(null);const items=computed(()=>filterShipments(store.shipments,{month:period.value}));const totals=computed(()=>metrics(items.value));const recent=computed(()=>items.value.slice(0,5));const attention=computed(()=>items.value.filter(s=>['Delayed','Customs'].includes(s.status)).slice(0,3));
const cards=computed(()=>[{label:'Total shipments',value:totals.value.total,icon:'Package',note:'All shipments in selected period',color:'green'},{label:'In progress',value:totals.value.active,icon:'Truck',note:'Booked, moving or at customs',color:'blue'},{label:'Delivered',value:totals.value.delivered,icon:'CircleCheck',note:`${totals.value.rate}% of selected shipments`,color:'green'},{label:'Needs attention',value:totals.value.delayed,icon:'CircleAlert',note:'Carrier delays to review',color:'orange'}]);
function edit(s){selected.value=null;editing.value=s;form.value=true;}function openForm(){editing.value=null;form.value=true;}function exportData(){const blob=new Blob([toCSV(items.value)],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='dispatch-overview.csv';a.click();URL.revokeObjectURL(url);store.notify('Overview exported as CSV.');}
</script>
<template><div class="page-heading"><div><div class="greeting">A LITTLE CLARITY FOR YOUR DAY</div><h1>Good to see you, {{store.settings.name.split(' ')[0]}} <span class="wave">✳</span></h1><p>Here’s what’s moving across your supply chain.</p></div><div class="heading-actions"><button class="btn" @click="exportData"><Icon name="Download"/>Export</button><button class="btn primary" @click="openForm"><Icon name="Plus"/>New shipment</button></div></div><div class="overview-filter"><h2>At a glance <span class="live-dot"></span></h2><label class="period-picker"><Icon name="CalendarDays" :size="15"/><select v-model="period" aria-label="Overview period"><option value="all">All time</option><option value="2026-10">October 2026</option><option value="2026-09">September 2026</option><option value="2026-08">August 2026</option></select></label></div><div class="metric-grid"><article class="metric-card" v-for="c in cards"><div><span>{{c.label}}</span><span class="metric-icon" :class="c.color"><Icon :name="c.icon" :size="18"/></span></div><strong>{{c.value.toLocaleString()}}</strong><p><span :class="c.color" class="metric-bullet">●</span>{{c.note}}</p></article></div><div class="dashboard-middle"><section class="panel map-panel"><div class="panel-heading"><div><h2>Your world, connected.</h2><p>A closer look at your international routes.</p></div><span class="small-pill">3 sample routes</span></div><RouteMap/></section><section class="panel attention-panel"><div class="panel-heading"><h2>Needs a closer look</h2><span class="number-pill">{{attention.length}}</span></div><div class="attention-list"><button v-for="s in attention" @click="selected=s"><span class="attention-icon" :class="{orange:s.status==='Delayed'}"><Icon :name="s.status==='Delayed'?'Clock':'Box'"/></span><span><b>{{s.status==='Delayed'?'Delivery rescheduled':'Customs clearance'}}</b><small>{{s.id}} · {{s.destination}}</small></span><Icon name="ChevronRight" :size="15"/></button><div v-if="!attention.length" class="empty-small"><Icon name="CircleCheck"/><p>Everything looks good.</p></div></div><div class="attention-note"><span class="note-icon"><Icon name="Activity" :size="17"/></span><div><b>Ahead of the unexpected.</b><p>Review exceptions early to keep your shipments moving.</p></div></div><RouterLink to="/shipments?status=Delayed" class="panel-bottom-link">Review delayed shipments<Icon name="ArrowRight" :size="16"/></RouterLink></section></div><section class="panel recent-panel"><div class="panel-heading"><div><h2>Recent shipments <span class="number-pill">{{items.length}}</span></h2><p>The latest movements, all in one place.</p></div><RouterLink to="/shipments" class="subtle-link">View all shipments<Icon name="ArrowUpRight" :size="15"/></RouterLink></div><ShipmentTable v-if="recent.length" :items="recent" :compact="store.settings.compact" @open="selected=$event" @sort="$router.push('/shipments')"/><div v-else class="empty-state"><Icon name="Package"/><h3>No shipments in this period</h3><p>Select another period or create a shipment.</p></div></section><div class="bottom-note"><Icon name="CircleCheck" :size="14"/>Your workspace is saved automatically on this device.<span>Make every move count.</span></div><ShipmentForm v-if="form" :shipment="editing" @close="form=false"/><ShipmentDetail v-if="selected" :shipment="selected" @close="selected=null" @edit="edit" @delete="store.remove($event);selected=null"/></template>
